COPY public.sql_query (id, code, query) FROM stdin;
2	rekap_pasien_no_reg	SELECT DISTINCT  \n\ta.no_reg\nFROM \nregpatient a\n--LEFT JOIN bill_patient_payment d ON c.bpid = d.bpid\nWHERE 1=1\n--AND TO_CHAR(c.bill_date, 'yyyymm') >= '202210'\n-- AND TO_CHAR(a.reg_date, 'yyyymm') >= '202401'\nAND a.ifirm_id = '1000';
1	rekap_pasien	SELECT DISTINCT  \na.no_reg, a.reg_date AS tgl_registrasi, a.discharge_date AS tgl_pulang, \nCASE WHEN a.discharge_date IS NULL THEN 'Masih Dirawat' ELSE 'Sudah Pulang' END AS status_rawat,\nCASE WHEN a.is_inpatient = TRUE THEN 'RAWAT INAP' ELSE 'RAWAT JALAN' END AS jenis_rawat,\nCASE WHEN a.discharge_date IS NULL THEN (date('now') - date(a.reg_date)) \n\t\tELSE (CASE WHEN (date(a.discharge_date) - date(a.reg_date) ) = 0 THEN 1 ELSE  (date(a.discharge_date) - date(a.reg_date)+1 ) END)\nEND as lama_rawat,\nb.tarif_cbg AS tarif_inacbg, \nb.tarif_rs AS tarif_rs_bridging,\ne.all_bill AS billing_rs, \n--c.total_amount AS dibayar_pasien, \n--c.total_discount AS dijamin,\n--c.total_amount + c.total_discount AS total_bill,\nb.finalisasi AS final_grouping, c.bill_date AS tgl_bill, \nc.is_closed, c.is_final, \nb.cbg_code AS kode_grouping, b.description, b.kelas_kirim, b.naik_kelas,\nb.kode_tarif, b.tarif_rs_non_bedah, b.tarif_rs_bedah, b.tarif_rs_konsultasi, b.tarif_rs_tenaga_ahli, b.tarif_rs_keperawatan, \nb.tarif_rs_penunjang, b.tarif_rs_radiologi, b.tarif_rs_laboratorium, b.tarif_rs_pelayanan_darah,\nb.tarif_rs_rehabilitasi, b.tarif_rs_kamar, b.tarif_rs_rawat_intensif, b.tarif_rs_obat, b.tarif_rs_alkes,\nb.tarif_rs_bmhp,  b.tarif_rs_sewa_alat, b.tarif_rs_obat_kemoterapi, b.cob,\nformat_rm(a.pid) AS mrn,  aa.name_real AS nama_pasien, a.no_sep, ab.name_real AS dokter_dpjp, \ndept.name_formal AS poly, d.class_name AS kelas, d.room_location AS ruang,\n f.tgl_mulai_titip, f.tgl_akhir_titip, f.lama_titip,\nCASE WHEN  g.class_name IS NOT NULL THEN g.class_name ELSE d.class_name END  AS hak_kelas, h.status_bill \n-- , b.*\nFROM \nregpatient a\nLEFT JOIN person aa ON aa.pid = a.pid\nLEFT JOIN person ab ON a.doctor_id = ab.pid\nLEFT JOIN department dept ON dept.did = a.current_dept_nr\nleft join history_cbg b ON a.regpid = b.regpid\nLEFT JOIN bill_patient c ON c.regpid = a.regpid AND c.status_obat <> 1\n/*\nLEFT JOIN (\n\t\tSELECT a.regpid, C.class_name, c.room_location \n\t\tFROM patient_bed_usage a\n\t\tINNER JOIN \n\t\t\t(SELECT regpid, MAX(exit_date) exit_date FROM patient_bed_usage GROUP BY regpid) b ON a.regpid = b.regpid AND a.exit_date = b.exit_date\n\t\tLEFT JOIN vhotel_allbed c ON c.hbid = a.hbid\n\t\t-- SELECT * FROM hotel_bed_dashboard\n\t\t) d ON d.regpid = a.regpid\n*/\nLEFT JOIN vhotel_allbed d ON a.current_bed_nr = d.hbid\nLEFT JOIN (SELECT regpid, SUM(amount+potongan) AS all_bill from bill_patient_row  GROUP BY regpid\n\t\t) e ON e.regpid = a.regpid\nLEFT JOIN (\n\t\t\tSELECT regpid, req_hcid, MIN(create_time) AS tgl_mulai_titip, MAX(create_time) AS tgl_akhir_titip,\n\t\t\tMAX(date(create_time)) - MIN(date(create_time)) AS lama_titip\n\t\t\tFROM \n\t\t\tpatient_request_class \n\t\t\t-- WHERE regpid = 344860\n\t\t\tGROUP BY regpid, req_hcid\n\t\t\t) f ON f.regpid = a.regpid\nLEFT JOIN hotel_class g ON g.hcid = f.req_hcid\nLEFT JOIN \n\t(\n\tSELECT a.regpid, a.pid, a.no_reg, a.current_dept_nr, a.referral_registration , aa.no_reg, aa.current_dept_nr, aa.referral_registration,\n\tCASE WHEN aa.no_reg IS NOT NULL THEN 'MERGE BILL' ELSE NULL END AS status_bill\n\tFROM regpatient a\n\tLEFT JOIN regpatient aa ON a.regpid = aa.referral_registration\n\tWHERE a.referral_registration IS NULL \n\t) h ON h.regpid = a.regpid\n--LEFT JOIN bill_patient_payment d ON c.bpid = d.bpid\nWHERE 1=1\n--AND TO_CHAR(c.bill_date, 'yyyymm') >= '202210'\n-- AND TO_CHAR(a.reg_date, 'yyyymm') >= '202401'\nAND a.ifirm_id = '1000'\n--AND a.no_reg = ${no_reg}\n\nLIMIT 100 
\.
